@@ -0,0 +1,15 @@
+/** LAN HTTP origins have getRandomValues, but may lack the secure-context-only randomUUID. */
+export function installRandomUUID(crypto: Pick<Crypto, 'getRandomValues'> & Partial<Pick<Crypto, 'randomUUID'>>) {
+  if (typeof crypto.randomUUID === 'function') return;
+  crypto.randomUUID = () => {
+    const bytes = crypto.getRandomValues(new Uint8Array(16));
+    // RFC 4122 version 4 and variant bits; retain cryptographic randomness.
+    bytes[6] = (bytes[6] & 0x0f) | 0x40;
+    bytes[8] = (bytes[8] & 0x3f) | 0x80;
+    const hex = Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('');
+    return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
+  };
+}
+
+// Run before App and its dependencies construct diagrams during module evaluation.
+installRandomUUID(globalThis.crypto);
