+      });
+      await waitFor(async () => Math.abs((await box()).x - moveBefore.x) < 2 && Math.abs((await box()).y - moveBefore.y) < 2);
+      assert.equal((await workspace()).history.headId, headBeforeMove, 'Toolbar Esc rolls back native pen movement');
