import { describe, expect, it } from 'vitest';
import { NativeSelectionOwnership, SelectionGestureController, type GestureStart } from '../selectionGesture';

const label = { diagramId: 'grid:a', nodeId: 'node', revision: 'r1' };
const start = (patch: Partial<GestureStart> = {}): GestureStart => ({ pointerId: 1, pointerType: 'touch',
  x: 20, y: 20, time: 0, tool: 'select', add: false, hit: label, ...patch });

describe('shared selection recognition', () => {
  it.each(['select', 'hand'] as const)('fingers only pan in %s, including double taps, tap-drag and move handles', tool => {
    const controller = new SelectionGestureController();
    for (const patch of [{}, { moveHandle: true }, { ctrl: true, add: true }]) {
      expect(controller.down(start({ tool, ...patch }))?.kind).toBe('pan');
      expect(controller.up(start({ time: 50 }))).toBeUndefined();
      expect(controller.down(start({ tool, time: 120, ...patch }))?.kind).toBe('pan');
      expect(controller.up(start({ time: 160 }))).toBeUndefined();
      controller.down(start({ tool, time: 200, ...patch }));
      expect(controller.move(start({ x: 80 }))?.kind).toBe('pan');
      expect(controller.up(start({ time: 260, x: 80 }))).toBeUndefined();
    }
  });
  it.each(['mouse', 'pen'])('remembers ever crossing slop for %s, even after returning to origin', pointerType => {
    const controller = new SelectionGestureController();
    controller.down(start({ pointerType, ctrl: pointerType === 'mouse' }));
    controller.move(start({ x: 50 }));
    expect(controller.up(start({ time: 90 }))?.kind).toBe('marquee');
  });
  it('does not reinterpret a returning mouse label drag as a click', () => {
    const controller = new SelectionGestureController();
    controller.down(start({ pointerType: 'mouse' })); controller.move(start({ x: 25 }));
    expect(controller.up(start({ time: 90 }))).toBeUndefined();
  });
  it('leaves stationary Ctrl-clicks unchanged so Ctrl-doubleclick can toggle a whole diagram', () => {
    const controller = new SelectionGestureController();
    controller.down(start({ pointerType: 'mouse', ctrl: true }));
    expect(controller.up(start({ time: 30 }))).toBeUndefined();
  });
  it('uses precise pen slop and selected tool semantics without a touch doubletap shortcut', () => {
    const controller = new SelectionGestureController();
    controller.down(start({ pointerType: 'pen' }));
    expect(controller.move(start({ x: 25 }))?.moved).toBe(true);
    controller.up(start({ time: 30, x: 25 }));
    expect(controller.down(start({ pointerType: 'pen', tool: 'hand', time: 80 }))).toMatchObject({ kind: 'pan' });
  });
  it('keeps desktop accumulation and retains explicit pen selection policy', () => {
    for (const [pointerType, add, policy] of [['pen', false, 'replace'], ['pen', true, 'add'], ['mouse', false, 'add']] as const) {
      const controller = new SelectionGestureController();
      expect(controller.down(start({ pointerType, add }))?.policy).toBe(policy);
    }
  });
  it('can select with a pen immediately after fingers finish panning', () => {
    const controller = new SelectionGestureController();
    controller.down(start()); controller.move(start({ x: 100 })); controller.up(start({ time: 50, x: 100 }));
    expect(controller.down(start({ pointerType: 'pen', time: 80 }))?.kind).toBe('marquee');
    expect(controller.up(start({ pointerType: 'pen', time: 90 }))).toEqual({ kind: 'tap', hit: label, policy: 'replace' });
  });
  it('cancels immediately on a second contact and holds the latch across native interrupts and partial releases', () => {
    const controller = new SelectionGestureController();
    controller.down(start()); controller.move(start({ x: 100 }));
    expect(controller.down(start({ pointerId: 2 }))).toBeUndefined();
    expect(controller.gesture).toBeUndefined();
    controller.cancel(); // Native pinch interrupt must not forget either contact.
    expect(controller.contacts.size).toBe(2);
    expect(controller.up(start({ pointerId: 2 }))).toBeUndefined();
    expect(controller.blocked).toBe(true);
    expect(controller.move(start({ x: 150 }))).toBeUndefined();
    expect(controller.down(start({ pointerId: 3 }))).toBeUndefined();
    controller.up(start({ pointerId: 3 })); controller.up(start());
    expect(controller.blocked).toBe(false);
    expect(controller.down(start())?.kind).toBe('pan');
  });
  it('leaves native move, Alt duplication, Space pan and mouse frame operations to the editor', () => {
    const controller = new SelectionGestureController();
    for (const patch of [{ moveHandle: true }, { pointerType: 'mouse', alt: true }, { pan: true }, { pointerType: 'mouse', hit: undefined }]) {
      expect(controller.down(start({ pointerType: 'mouse', ...patch }))?.kind).toMatch(/native|move/);
      expect(controller.up(start())).toBeUndefined();
    }
  });
  it('retains application ownership through repeated settlements until an intended native operation', () => {
    const ownership = new NativeSelectionOwnership();
    expect(ownership.captureSelection).toBe(false);
    ownership.claim('native'); expect(ownership.captureSelection).toBe(true);
    ownership.claim('application');
    for (let frame = 0; frame < 5; frame++) expect(ownership.captureSelection).toBe(false);
  });
});

sources.domain/mapping/selection/completeMarquee:
import type { LineGridScene, ResolvedGridBox } from '../../core/diagrams/lineGrid';
import { diagramSelectionItem, regionSelectionItem } from './selectionState';
import { updateSelection, type CanvasMarqueeSelection } from './canvasSelection';
import type { SelectionPolicy } from './selectionGesture';
import { addDisplayNode, displayGeometry, type SelectionRegion } from '../workspace/displayModel';
import { initialSelectionSurface, type MappingCanvasState } from '../workspace/mappingWorkspace';

/** Commit membership and retain reusable region identities and their display surfaces. */
export function completeMarquee(current: MappingCanvasState, marquee: CanvasMarqueeSelection,
  scene: LineGridScene, boxes: readonly ResolvedGridBox[], policy: SelectionPolicy): MappingCanvasState {
  const items = marquee.diagramIds.map(diagramSelectionItem);
  for (const { boxId, rect } of marquee.regions) {
    if (marquee.diagramIds.includes(`grid:${boxId}`)) continue;
    const box = boxes.find(box => box.box.id === boxId), diagram = box?.contentId && scene.contents[box.contentId];
    if (!diagram) continue;
    const existing = Object.values(current.display.nodes).find((node): node is SelectionRegion => node.kind === 'selection'
      && node.sourceBoxId === boxId && node.sourceAscii === diagram.content.ascii
      && JSON.stringify(node.rect) === JSON.stringify(rect));
    items.push(regionSelectionItem(diagram, boxId, rect, existing?.id));
  }
  let next = updateSelection(current, { type: policy, items });
  const surfaces = { ...next.controls.surfaces };
  let last: SelectionRegion | undefined;
  for (const requested of items.filter(item => item.region)) {
    // The reducer may reuse an existing identity for a repeated gesture.
    const item = next.selection.items.find(item => item.region && item.displayNodeId === requested.displayNodeId
      && JSON.stringify(item.region.rect) === JSON.stringify(requested.region!.rect))!;
    const region = item.region!, existing = next.display.nodes[item.id];
    last = { ...displayGeometry(), id: item.id, kind: 'selection', childIds: [], expansion: 'expanded', displayMode: 'stacked',
      ...(existing?.kind === 'selection' ? existing : {}), sourceBoxId: item.displayNodeId.slice(5),
      sourceContentId: region.sourceContentId, sourceAscii: region.sourceAscii, sourceRevisionId: region.sourceRevisionId,
      rect: region.rect, selectedIds: [...region.selectedIds] };
    next = { ...next, display: existing ? { ...next.display, nodes: { ...next.display.nodes, [last.id]: last } }
      : addDisplayNode(next.display, last) };
    surfaces[last.id] = { ...surfaces[last.id] ?? initialSelectionSurface(), actionsOpen: false };
  }
  return { ...next, controls: { ...next.controls, surfaces, selectionFocusId: last?.id ?? null,
    ...(last ? { activeBoxId: last.sourceBoxId } : {}) } };
}

sources.domain/mapping/selection/selectionGestur:
import type { SelectionBounds } from './canvasSelection';

export type SelectionPolicy = 'add' | 'replace';
export interface SelectionHit { diagramId: string; nodeId?: string; revision?: string }
export interface GesturePoint { pointerId: number; pointerType: string; x: number; y: number; time: number }
export interface GestureStart extends GesturePoint {
  hit?: SelectionHit; tool: 'select' | 'hand'; add: boolean;
  ctrl?: boolean; meta?: boolean; shift?: boolean; alt?: boolean; pan?: boolean; moveHandle?: boolean;
}
export type GestureKind = 'marquee' | 'pan' | 'node' | 'native' | 'move' | 'blocked';
export interface SelectionGesture {
  start: GestureStart; kind: GestureKind; policy: SelectionPolicy; moved: boolean; bounds: SelectionBounds;
}
export type GestureCompletion = { kind: 'marquee'; bounds: SelectionBounds; policy: SelectionPolicy }
  | { kind: 'tap'; hit: SelectionHit; policy: SelectionPolicy };

/** Recognition in screen pixels, shared by mouse, pen and touch. No document or SDK state. */
export class SelectionGestureController {
  readonly contacts = new Set<number>();
  gesture?: SelectionGesture;
  blocked = false;
  constructor(readonly slop = 4, readonly touchSlop = 10) {}
  down(start: GestureStart): SelectionGesture | undefined {
    this.contacts.add(start.pointerId);
    if (this.contacts.size > 1 || this.blocked) { this.cancel(); this.blocked = true; return; }
    const direct = start.pointerType !== 'mouse';
    const kind: GestureKind = start.pointerType === 'touch' ? 'pan'
      : start.moveHandle ? 'move' : start.pan ? 'native'
      : direct ? (start.tool === 'select' ? 'marquee' : 'pan')
      : start.ctrl && !start.meta ? 'marquee'
      : start.shift && !start.meta ? 'blocked'
      : start.hit?.nodeId && !start.meta && !start.alt ? 'node' : 'native';
    return this.gesture = { start, kind, policy: direct ? (start.add ? 'add' : 'replace') : 'add',
      moved: false, bounds: { left: start.x, right: start.x, top: start.y, bottom: start.y } };
  }
  move(point: GesturePoint) {
    const gesture = this.gesture;
    if (!gesture || point.pointerId !== gesture.start.pointerId) return;
    gesture.moved ||= Math.hypot(point.x - gesture.start.x, point.y - gesture.start.y) > (gesture.start.pointerType === 'touch' ? this.touchSlop : this.slop);
    gesture.bounds = { left: Math.min(point.x, gesture.start.x), right: Math.max(point.x, gesture.start.x),
      top: Math.min(point.y, gesture.start.y), bottom: Math.max(point.y, gesture.start.y) };
    return gesture;
  }
  up(point: GesturePoint): GestureCompletion | undefined {
    const gesture = this.move(point);
    this.contacts.delete(point.pointerId);
    if (!this.contacts.size) this.blocked = false;
    if (!gesture) return;
    this.gesture = undefined;
    if (gesture.start.pointerType === 'touch') return;
    if (gesture.kind === 'marquee' && gesture.moved) return { kind: 'marquee', bounds: gesture.bounds, policy: gesture.policy };
    if (gesture.moved || ['native', 'move', 'blocked'].includes(gesture.kind)) return;
    if (gesture.start.pointerType === 'mouse' && gesture.kind !== 'node') return;
    if (gesture.start.hit) return { kind: 'tap', hit: gesture.start.hit, policy: gesture.policy };
  }
  /** Keep the multi-contact latch until every contact has left, including after cancellation. */
  cancel() { this.gesture = undefined; }
  reset() { this.cancel(); this.contacts.clear(); this.blocked = false; }
}

/** A DOM release is earlier than native pointer-up/pinch settlement. Ownership
 * remains latched until the next intentionally native operation begins. */
export class NativeSelectionOwnership {
  private owner: 'application' | 'native' = 'application';
  claim(owner: 'application' | 'native') { this.owner = owner; }
  get captureSelection() { return this.owner === 'native'; }
}

